// Run Once for All Items

const TZ = 'America/Mexico_City';
const MAX_LEN = 4096;

// --- Utilidades ---
function deepClone(o) { return JSON.parse(JSON.stringify(o)); }

function saludoPorHora() {
  try {
    const hour = parseInt(new Intl.DateTimeFormat('es-MX', { timeZone: TZ, hour: 'numeric', hour12: false }).format(new Date()), 10);
    if (hour >= 5 && hour < 12) return '¡Buenos días!';
    if (hour >= 12 && hour < 20) return '¡Buenas tardes!';
    return '¡Buenas noches!';
  } catch {
    const h = new Date().getHours();
    if (h >= 5 && h < 12) return '¡Buenos días!';
    if (h >= 12 && h < 20) return '¡Buenas tardes!';
    return '¡Buenas noches!';
  }
}

function hashCode(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = ((h << 5) - h) + str.charCodeAt(i); h |= 0; }
  return h;
}

function fechaClave() {
  try {
    return new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
  } catch {
    const d = new Date(); const mm = String(d.getMonth() + 1).padStart(2,'0'); const dd = String(d.getDate()).padStart(2,'0');
    return `${d.getFullYear()}-${mm}-${dd}`;
  }
}

function setInboundText(body, newText) {
  // Forma inbound (webhook): body.messages[0].text.body
  if (Array.isArray(body?.messages) && body.messages.length > 0) {
    const m = body.messages[0];
    if (m && typeof m === 'object' && (m.type === 'text' || m.text)) {
      m.type = 'text';
      m.text = m.text || {};
      m.text.body = newText;
      return true;
    }
  }
  return false;
}

function setOutboundText(body, newText) {
  // Forma outbound (envío): body.type/text.body en raíz
  if (body?.type === 'text' || body?.text) {
    body.type = 'text';
    body.text = body.text || {};
    body.text.body = newText;
    return true;
  }
  return false;
}

// --- 1) Entrada ---
const input = items[0]?.json || {};
const originalRaw = input.wa_body;
const keep = input.wa_keep_body === true;

if (keep) {
  return [{ json: { wa_body: originalRaw } }];
}

// No hay body
if (originalRaw == null) {
  return [{ json: { wa_body: null, _note: 'wa_body ausente' } }];
}

// Determinar tipo y clonar/parsear
let wasString = false;
let body;
if (typeof originalRaw === 'string') {
  wasString = true;
  try {
    body = JSON.parse(originalRaw);
  } catch (e) {
    // si es string pero no JSON válido, no lo tocamos
    return [{ json: { wa_body: originalRaw, _error: 'wa_body no es JSON válido' } }];
  }
} else if (typeof originalRaw === 'object') {
  body = deepClone(originalRaw);
} else {
  return [{ json: { wa_body: originalRaw, _error: 'wa_body no es objeto ni string' } }];
}

// --- 2) Mensaje de introducción determinístico (por día y destinatario) ---
const saludo = saludoPorHora();
const baseMsgs = [
  'Me gustaría obtener información, por favor.',
  'Quisiera conocer más sobre sus servicios.',
  'Estoy interesad@ en recibir información.',
  'Quisiera hacer algunas consultas, por favor.',
  '¿Podrían brindarme información, por favor?'
];

const toCandidate =
  body?.to ??
  body?.messages?.[0]?.to ??
  body?.recipient_id ??
  body?.contacts?.[0]?.wa_id ??
  '';

const idxKey = `${toCandidate}-${fechaClave()}`;
const idx = Math.abs(hashCode(idxKey)) % baseMsgs.length;

let mensajeFinal = `${saludo} ${baseMsgs[idx]}`;
if (mensajeFinal.length > MAX_LEN) mensajeFinal = mensajeFinal.slice(0, MAX_LEN);

// --- 3) Aplicar cambio (inbound u outbound) ---
let updated = setInboundText(body, mensajeFinal);
if (!updated) updated = setOutboundText(body, mensajeFinal);

// Si no pudo escribir, regresamos igual para no romper el flujo
if (!updated) {
  const untouched = wasString ? originalRaw : originalRaw;
  return [{ json: { wa_body: untouched, _note: 'No se encontró ruta text.body' } }];
}

// --- 4) Salida en el mismo tipo que entró ---
const finalBody = wasString ? JSON.stringify(body) : body;
return [{ json: { wa_body: finalBody } }];

