const MAX_LEN = 30;

return items.map(({ json }) => {
  // Lee el mensaje del Set anterior (acepta ambos nombres)
  const raw =
    (json.validation_message ?? json.validacion_message ?? "").toString();

  if (!raw) {
    return { json: { ...json, error: "validation_message vacío o no encontrado" } };
  }

  // Eliminar el prefijo VALIDAR-
  const code = raw.replace(PREFIX, "").trim();

  // (Opcional) Validar longitud 25-30
  const length_ok = code.length >= MIN_LEN && code.length <= MAX_LEN;

  return {
    json: {
      ...json,               // conserva todos los campos originales
      validation_message: raw,  // normaliza el nombre si quieres
      code,
      length_ok              // útil para un IF posterior
    }
  };
});

