  const seleccionRaw = json.seleccion;  // viene como string desde WhatsApp
  const seleccion = parseInt(seleccionRaw, 10);

  // Validar que opciones sea array
  if (!Array.isArray(opciones)) {
    return { json: { error: "El campo 'opciones' no es un array válido." } };
