function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

return [
  {
    json: {
      uuid: uuidv4(),
      now: new Date().toLocaleString('es-MX', {
  timeZone: 'America/Mexico_City'
})
    }
  }
];

// 1) Recupera tus variables del Set anterior
const input = items[0].json;
const htmlResponseBody  = JSON.parse(input.htmlResponseBody);     // string JSON con data_multi
const selectedStudentNo  = parseInt(input.selected_student, 10);

// 2) Función principal
try {
  // Parsear sólo si viene como string
  const parsed = typeof htmlResponseBody === 'string'
    ? JSON.parse(htmlResponseBody)
    : htmlResponseBody;

  const students = parsed.data.data_multi;
  if (!Array.isArray(students) || students.length === 0) {
    return [{
      json: {
        status:  "error",
        message: "No se encontraron datos de estudiantes",
      }
    }];
  }

  // Validar rango
  if (isNaN(selectedStudentNo)
      || selectedStudentNo < 1
      || selectedStudentNo > students.length) {
    return [{
      json: {
        status:  "error",
        message: `Por favor selecciona un número entre 1 y ${students.length}`,
      }
    }];
  }

  // Selección
  const sel = students[selectedStudentNo - 1];
  return [{
    json: {
      status:            "success",
      message:           `Has seleccionado a ${sel.first_name} ${sel.last_name}`,
      selected_student:  sel,
    }
  }];

} catch (err) {
  return [{
    json: {
      status:  "error",
      message: `Error al procesar la solicitud: ${err.message}`,
    }
  }];
}

